    ('exodus', '03', 'Out of Egypt', 'Freedom, covenant & the wilderness', 'Exodus–Deuteronomy · Jubilees', 'Exodus chronology and routes debated'),
    ('land', '04', 'A people in the land', 'Joshua, judges, Ruth & Samuel', 'Joshua · Judges · Ruth · 1 Samuel', 'Narrative sequence · overlapping generations'),
    ('united', '05', 'A kingdom rises', 'Saul, David, Solomon & the temple', 'Samuel · Kings · Chronicles', 'Conventionally c. 1050–931 BCE'),
    ('divided', '06', 'Two kingdoms', 'Israel and Judah, side by side', 'Kings · Chronicles · the prophets', 'Conventionally c. 931–722 BCE'),
    ('exile', '07', 'The road to exile', 'Reform, siege & a surviving promise', '2 Kings · Jeremiah · Ezekiel', 'c. 722–561 BCE'),
