entries = []
def refs(spec):
    result=[]
    for part in spec.split(';'):
        parts=part.strip().split(':')
        if not parts[0]: continue
        book,chapter=parts[0].split()
        result.append(dict(book=book,chapter=int(chapter),verses=parts[1] if len(parts)>1 else ''))
    return result

def add(id,title,era,kind,summary,ref,loc='',links='',collection='shared',date='',bce=None,primary=True,note=''):
    entries.append(dict(id=id,title=title,era=era,kind=kind,summary=summary,refs=refs(ref),places=loc.split(),related=links.split(),collection=collection,date=date or next(e['dating'] for e in eras if e['id']==era),bce=bce,primary=primary,note=note))

# The primeval story deliberately includes the Ethiopian-preserved accounts in
# the main narrative, with the source of each expansion named explicitly.
add('creation','In the beginning','beginnings','story','Light breaks into darkness. Genesis opens with a world ordered and called good, and with human beings entrusted with responsibility within it. Jubilees retells creation within a revelation to Moses and gives particular attention to the heavenly world and the Sabbath. Read the accounts alongside one another: the shared story matters, and so do the details each text chooses to tell.','GEN 1;GEN 2:1-3;JUB 2',links='eden jubilees-sinai cosmic-order',collection='shared')
add('eden','A garden, a choice, an exile','beginnings','story','The garden brings the human relationship with God, the earth, and one another into focus. The command, the serpent’s question, and the taking of the fruit lead to shame and expulsion. Jubilees 3 retells the garden story with its own calendar and details. Neither account supplies coordinates that allow us to put a reliable Eden pin on a modern map.','GEN 2;GEN 3;JUB 3',links='adam eve cain-abel creation',note='Eden is intentionally unmapped. Proposed modern identifications are not established by the text.')
add('cain-abel','A brother’s blood','beginnings','story','Cain and Abel bring offerings, but the story turns on anger and the refusal to master it. After Abel’s death, God asks Cain about his brother. The violence of one household becomes a thread running toward the violence of the wider earth before the Flood. Cain’s descendant Enoch is not the Enoch in Seth’s line.','GEN 4;JUB 4',links='adam eve enoch flood')
add('enoch','Enoch, who walked with God','beginnings','person','Genesis gives Enoch a startlingly brief departure: he walks with God, and God takes him. In 1 Enoch, the same ancestral figure becomes a scribe, intercessor, and witness to heavenly judgment. Jubilees also remembers him as a writer and observer of the heavens. This is Enoch the son of Jared, seventh in the genealogy beginning with Adam—not Cain’s son of the same name.','GEN 5:18-24;ENO 12;JUB 4',links='watchers heavenly-court angel-guides cosmic-order noah-birth',collection='enoch')
add('watchers','The Watchers descend','beginnings','story','Genesis 6 speaks briefly of the sons of God, human daughters, and the Nephilim. 1 Enoch 6–7 tells a longer account: a group of heavenly beings swears an oath on Mount Hermon, takes wives, and produces destructive giants. The mountain, the oath, and the named leaders come from 1 Enoch; Genesis itself does not supply those details.','GEN 6:1-4;ENO 6;ENO 7;JUB 5','hermon','enoch forbidden-arts judgment-watchers flood',collection='enoch',note='This connection compares accounts. It does not treat every interpretation of Genesis’s “sons of God” as identical.')
add('forbidden-arts','Knowledge without wisdom','beginnings','story','In 1 Enoch 8, instruction in weapons, adornment, enchantments, and the signs of the heavens becomes part of the world’s corruption. The story asks what happens when knowledge serves violence and domination. These particular teachings and their named teachers belong to the Enochic account; they should not be inserted into Genesis as if Genesis listed them.','ENO 8;ENO 9',links='watchers judgment-watchers cosmic-order',collection='enoch')
add('judgment-watchers','The cry of the earth','beginnings','story','The suffering earth reaches heaven. 1 Enoch names angelic witnesses who bring the violence before God, then describes judgment on the Watchers and their offspring. Noah is warned of the coming destruction. Enoch later carries a petition from the fallen Watchers, but his answer is not the pardon they seek.','ENO 9;ENO 10;ENO 13;ENO 15',links='watchers enoch noah flood mastema',collection='enoch')
add('heavenly-court','Before the heavenly throne','beginnings','vision','Enoch’s vision moves through a fearsome heavenly house to the throne of the Great Glory. The scene presents judgment from the viewpoint of heaven rather than from a battlefield or palace. It offers a useful comparison with prophetic throne visions, while its imagery and message remain those of 1 Enoch.','ENO 14;ENO 15;ISA 6;EZK 1',links='enoch angel-guides isaiah ezekiel',collection='enoch')
add('angel-guides','Journeys beyond the familiar world','beginnings','vision','Enoch is led through places of judgment, mountains, the dwelling places of the dead, and visions of the tree reserved for the righteous. These are visionary journeys, not a travel itinerary we can reliably draw across modern countries. The named guides and landscapes open a window into the book’s moral geography.','ENO 20;ENO 22;ENO 24;ENO 25',links='enoch heavenly-court eden cosmic-order',collection='enoch',note='Visionary locations are not plotted as surveyed geographic places.')
add('cosmic-order','The lights and the calendar','beginnings','vision','The Astronomical Book within 1 Enoch describes heavenly movements under angelic instruction. Jubilees emphasizes a 364-day calendar and the danger of losing the proper order of festivals. Their interest in ordered time connects creation, worship, and faithful living. These ancient accounts are presented as their own textual traditions, not as modern astronomical models.','ENO 72;ENO 82;JUB 6;GEN 1:14-19',links='creation enoch jubilees-sinai',collection='enoch')
add('noah-birth','The astonishing birth of Noah','beginnings','story','1 Enoch 106–107 tells a story absent from Genesis: Lamech is alarmed by his newborn son’s extraordinary appearance and asks Methuselah for help. Methuselah turns to Enoch, who explains the child’s identity and the coming Flood. Keeping the source label visible lets us explore this vivid family story without confusing it with Genesis’s much shorter notice of Noah’s birth.','ENO 106;ENO 107;GEN 5:28-32',links='enoch methuselah lamech noah flood',collection='enoch')
add('noah','Noah and a world in crisis','beginnings','person','Noah stands at the hinge between the world before the Flood and the families after it. Genesis emphasizes his righteousness, his household, and his obedience in building the ark. The Enochic and Jubilees traditions add further accounts of warning, corruption, and the struggle with evil. His sons Shem, Ham, and Japheth become the starting points of the post-Flood genealogies.','GEN 6;GEN 9;JUB 5',links='noah-birth flood covenant-noah mastema')
add('flood','The Flood','beginnings','story','Violence has filled the earth. Genesis describes the ark, rising waters, the preservation of living creatures, and the eventual return to dry ground. 1 Enoch and Jubilees connect the catastrophe with the corruption associated with the Watchers. The texts meet around judgment and preservation, though their narrative details are not interchangeable.','GEN 6;GEN 7;GEN 8;ENO 10;JUB 5','ararat','noah watchers covenant-noah')
add('covenant-noah','A bow in the clouds','beginnings','story','After the Flood, the story opens outward to every living creature. Genesis describes a covenant, a prohibition on bloodshed, and the bow in the clouds as its sign. Jubilees 6 connects Noah’s sacrifice and covenant with sacred time and the Feast of Weeks. A new beginning does not erase the need for justice or faithful remembrance.','GEN 9:1-17;JUB 6',links='flood noah cosmic-order divided-earth')
add('mastema','Noah’s prayer and Mastema','beginnings','story','Jubilees 10 returns to the problem of evil after the Flood. Noah prays for his descendants when destructive spirits trouble them. Mastema asks that a portion remain under his authority; the account also describes instruction in healing. This is a distinct Jubilees narrative, useful for seeing how that book carries the consequences of the primeval crisis into later generations.','JUB 10',links='noah judgment-watchers offering-isaac',collection='jubilees')
add('divided-earth','Families become nations','beginnings','story','Genesis 10 arranges the peoples of the world through the descendants of Noah’s sons. Jubilees 8–9 offers its own account of the division of the earth, with boundaries and solemn warnings. These are ancient ways of describing the world and its peoples; they are not modern ethnic classifications or precise national borders.','GEN 10;JUB 8;JUB 9',links='noah babel abraham-call',collection='shared')
add('babel','A city and a scattered people','beginnings','story','In the land of Shinar, people build a city and tower to make a name and resist being scattered. The confusion of language turns the project inside out. The next great movement in Genesis is toward one family called to become a blessing for the nations. Jubilees 10 also retells the tower episode.','GEN 11:1-9;JUB 10','babylon','divided-earth abraham-call',note='The map marks Babylon as a regional reference, not the location of an archaeologically identified biblical tower.')

add('abraham-call','Leave your country','patriarchs','story','Abram’s journey begins with a promise that reaches beyond his household: blessing for the families of the earth. Haran, Shechem, Bethel, and Egypt become places where that promise is tested and carried forward. The lines on the atlas connect named destinations; they do not claim to reproduce ancient roads or exact routes.','GEN 11:27-32;GEN 12;JUB 12;JUB 13','ur haran shechem bethel egypt','abraham sarah fire-idols lot')
add('fire-idols','Abraham and his father’s idols','patriarchs','story','Jubilees tells more of Abram’s early life than Genesis does. He challenges idol worship and burns the house of idols; his brother Haran dies in the fire. The narrative also describes Abram rejecting dependence on heavenly signs and turning in prayer to the Creator. These episodes belong to Jubilees 12, not to Genesis’s brief genealogy.','JUB 12;GEN 11:27-32','ur haran','abraham abraham-call cosmic-order',collection='jubilees')
add('melchizedek','A meeting with Melchizedek','patriarchs','person','After the rescue of Lot, Abram meets Melchizedek, king of Salem and priest of God Most High. Bread, wine, blessing, and a tenth of the spoils mark this short encounter. Psalm 110 and Hebrews later return to this figure; those later readings can be followed without turning the few verses of Genesis into a full biography it does not provide.','GEN 14:17-24;PSA 110;HEB 7',links='abraham lot',note='Salem is often identified with Jerusalem; the atlas does not require that identification for this encounter.')
add('sodom','Lot and the cities of the plain','patriarchs','story','Abraham’s questions about justice lead into the story of Lot, threatened visitors, escape, and the destruction of the cities. Genesis also preserves a difficult account of Lot’s family after the catastrophe. The narrative connects Abraham’s household with the origins of Moab and Ammon, but the cities’ exact locations remain disputed.','GEN 18;GEN 19',links='abraham lot ruth')
add('offering-isaac','Abraham’s test','patriarchs','story','Genesis presents God testing Abraham in the command concerning Isaac, ending with the provision of a ram. Jubilees 17–18 places the test within a heavenly challenge involving Mastema and adds its own framing. Read them side by side: shared figures and action, but a different account of what precedes the trial.','GEN 22;JUB 17;JUB 18',links='abraham isaac mastema',collection='shared')
add('jacob-bethel','A stairway at Bethel','patriarchs','story','On the road away from home, Jacob dreams of a stairway reaching heaven and hears the ancestral promise renewed. He names the place Bethel. Centuries later Bethel becomes a royal sanctuary under Jeroboam. A place of encounter in one generation becomes a place of prophetic dispute in another.','GEN 28:10-22;GEN 35:1-15;1KI 12:25-33','bethel','jacob jeroboam-1 kingdom-split')
add('jacob-wrestles','A new name at the river','patriarchs','story','Before meeting Esau again, Jacob wrestles through the night and receives the name Israel. The reconciliation that follows does not erase the wounds or fears that brought the brothers to this point. The name of one man becomes the name of a people—and later a kingdom—so the atlas keeps those different uses of “Israel” distinct.','GEN 32;GEN 33','jabbok','jacob esau twelve-tribes')
add('twelve-tribes','The household of Israel','patriarchs','story','Jacob’s children come through Leah, Rachel, Bilhah, and Zilpah. Their family becomes the basis of the tribal story, but lists of tribes vary with purpose: Levi has a distinct role, and Joseph may be represented by Ephraim and Manasseh. The family tree shows named relationships, not a claim that every biblical tribal list has the same twelve entries.','GEN 29;GEN 30;GEN 35:16-26;GEN 48','haran','jacob leah rachel joseph judah')
add('sold-joseph','Joseph is sold','patriarchs','story','A favored son, dreams, and a bloodied garment tear a household apart. Joseph reaches Egypt through betrayal and sale. Jubilees 34 retells the episode and connects the family’s grief to remembrance. Genesis will later revisit the brothers’ responsibility through Joseph’s own words about preservation and providence.','GEN 37;JUB 34','egypt','joseph jacob judah egypt-family')
add('judah-tamar','Tamar interrupts the family story','patriarchs','story','While Joseph’s story unfolds, Genesis pauses over Judah and Tamar. Denied the future she had been promised, Tamar forces Judah to recognize his own failure. Their son Perez belongs to the genealogy later leading to David. The family line carries difficult stories, not a polished parade of faultless ancestors.','GEN 38;RUT 4:18-22',links='judah tamar perez ruth david')
add('egypt-family','A family preserved in Egypt','patriarchs','story','Joseph’s rise in Egypt places him in a position to preserve the family during famine. Reconciliation takes time and tests the brothers’ willingness to protect Benjamin. Jacob’s household settles in Egypt, and Genesis ends with Joseph’s death and his request concerning his bones—a promise that reaches into Exodus and Joshua.','GEN 45;GEN 46;GEN 50;EXO 13:19;JOS 24:32','egypt shechem','joseph jacob moses passover')

add('burning-bush','A call from the burning bush','exodus','story','Moses encounters a bush burning without being consumed. The call is grounded in God’s attention to the suffering of the enslaved people. Moses objects, asks questions, and is sent back toward Pharaoh with Aaron’s help. Horeb and Sinai are linked in the biblical tradition, but their precise geographical identification remains debated.','EXO 3;EXO 4','sinai egypt','moses aaron passover')
add('passover','A night of departure','exodus','story','The confrontation with Pharaoh reaches the night of Passover. A meal, marked doorways, judgment, and hurried departure become a memory to be kept across generations. Jubilees 49 gives its own instruction about observing the festival. The atlas does not identify an unnamed Pharaoh or assign a single settled date to the Exodus.','EXO 12;EXO 13;JUB 49','egypt','moses aaron sea-crossing egypt-family')
add('sea-crossing','Through the sea','exodus','story','Trapped between the sea and an approaching army, the people pass through on dry ground in Exodus’s account. Moses and Miriam lead songs of deliverance afterward. The Hebrew name Yam Suph is often rendered “Red Sea” or “Sea of Reeds”; the precise crossing site is not established here.','EXO 14;EXO 15',links='moses miriam passover sinai-covenant',note='No exact crossing point or route is plotted.')
add('sinai-covenant','Covenant at the mountain','exodus','story','Rescue from Egypt leads to a covenant and a way of life. At Sinai the people hear the commandments, and Moses receives instruction for the community. The mountain becomes central to Exodus and to the framing of Jubilees: the latter presents its account of early history as revelation given there.','EXO 19;EXO 20;EXO 24;JUB 1','sinai','moses jubilees-sinai golden-calf tabernacle')
add('jubilees-sinai','The angel’s account to Moses','exodus','vision','Jubilees opens at Sinai, looking backward. God directs Moses to record the divisions of history, and an angel of the presence recounts creation and the generations. That framing explains why Jubilees can sit beside the early Genesis stories in the story view while its scene of revelation belongs here, with Moses.','JUB 1;JUB 2','sinai','creation enoch cosmic-order sinai-covenant',collection='jubilees',note='Story setting and the date of a book’s composition are different questions.')
add('golden-calf','The calf and the broken tablets','exodus','story','While Moses is on the mountain, the people ask Aaron for gods to go before them. The calf, the broken tablets, and Moses’s intercession expose how quickly a rescued people can turn aside. Kings later describes Jeroboam’s calves at Bethel and Dan, giving readers a powerful textual comparison across centuries.','EXO 32;EXO 34;1KI 12:28-30','sinai bethel','aaron moses jeroboam-1 tabernacle')
add('tabernacle','A dwelling in the wilderness','exodus','story','The sanctuary is made to travel with the people. Artisans, materials, the ark, and ordered service occupy much of the latter part of Exodus, ending with the cloud and glory filling the dwelling. Follow the ark forward to Shiloh and Jerusalem to see how the story of divine presence intersects with the story of kings.','EXO 25;EXO 31;EXO 40','sinai','ark-captured ark-jerusalem temple')
add('spies','At the edge of the land','exodus','story','The scouts return with fruit and conflicting judgments. Caleb and Joshua urge trust, while the community recoils in fear. The ensuing wilderness years shape the transition between generations. The reference to Anak’s descendants connects this account with later encounters in the land, without identifying every biblical giant tradition as the same story.','NUM 13;NUM 14','kadesh','joshua moses-farewell goliath')
add('korah','A challenge in the camp','exodus','story','Korah, Dathan, and Abiram challenge the leadership of Moses and Aaron. Numbers presents the conflict as a dispute over authority and holiness, followed by judgment and renewed instruction concerning priestly service. The community’s internal fractures are as important to the wilderness story as its external enemies.','NUM 16;NUM 17',links='moses aaron tabernacle')
add('balaam','A hired curse becomes a blessing','exodus','person','Balak of Moab summons Balaam to curse Israel. The journey includes the startling episode of the speaking donkey; the speeches repeatedly turn toward blessing instead. Later passages remember Balaam critically. Reading those texts together prevents a single dramatic episode from becoming the whole account of this complicated figure.','NUM 22;NUM 23;NUM 24;NUM 31:16','moab','moses joshua')
add('moses-farewell','A view from Nebo','exodus','story','Moses addresses a new generation in Deuteronomy, then views the land from Nebo before his death. Joshua receives the task of leading onward. The transition joins memory, covenant, and unfinished hope: the one who leads the people out of Egypt does not lead them across the Jordan.','DEU 31;DEU 34','nebo moab','moses joshua jordan-crossing')

add('jordan-crossing','Across the Jordan','land','story','The ark goes before the people as they cross the Jordan. Memorial stones are set up so future children can ask what happened here. Joshua’s opening movement deliberately recalls the sea crossing, connecting a new generation with the story of deliverance from Egypt.','JOS 3;JOS 4','jordan jericho','joshua sea-crossing jericho-battle')
add('jericho-battle','Jericho and Rahab','land','battle','Rahab shelters the spies and asks that her household be spared. Joshua’s account then describes the circling of Jericho and the fall of its walls. The same city contains a story of rescue and a difficult account of destruction. The atlas follows the narrative without claiming that archaeological questions about its dating are settled.','JOS 2;JOS 6','jericho','rahab joshua jordan-crossing')
add('shechem-covenant','Choose whom you will serve','land','story','Near the end of Joshua’s story, the people gather at Shechem. The address reaches back to Abraham’s family beyond the river, tying the present generation to the ancestral call. Joseph’s bones are also buried at Shechem. Place, memory, covenant, and a long-delayed family promise meet here.','JOS 24','shechem','joshua abraham-call egypt-family kingdom-split')
add('deborah','Deborah, Barak, and a song','land','prophet','Deborah serves as prophet and judge. She summons Barak, and the story of conflict with Sisera culminates in Jael’s action and a victory song. Judges 4 and 5 tell the episode in prose and poetry. Reading both lets us hear the same deliverance through different literary voices.','JDG 4;JDG 5','megiddo','gideon samuel')
add('gideon','Gideon and the reduced army','land','person','Called while threshing in fear, Gideon becomes the leader of a force deliberately reduced before battle with Midian. The aftermath complicates the victory: an ephod becomes a snare, and his family’s story turns toward Abimelech’s violence. Judges asks us to look beyond the exciting battle to the consequences of leadership.','JDG 6;JDG 7;JDG 8;JDG 9',links='deborah jephthah samson')
add('jephthah','Jephthah’s terrible vow','land','person','An excluded son becomes a military leader, but his vow brings devastation into his own household. Judges leaves a deeply troubling story about victory, speech, and a daughter whose future is taken from her. Interpretations differ over the precise fulfillment of the vow; the reader can examine the passage rather than having that debate silently resolved for them.','JDG 11;JDG 12',links='gideon samson')
add('samson','Strength and captivity','land','person','Samson’s extraordinary strength unfolds alongside impulsive choices and conflict with the Philistines. Delilah’s betrayal leads to imprisonment in Gaza; the final scene brings destruction upon both Samson and his captors. His story closes without the uncomplicated peace a reader might expect from a deliverer.','JDG 13;JDG 14;JDG 16','gaza','gideon saul')
add('ruth','Ruth chooses to stay','land','person','A famine, bereavement, and the journey from Moab bring Ruth and Naomi to Bethlehem. Ruth’s loyalty and Boaz’s protection lead to a new household. The book ends with a genealogy: Ruth becomes the great-grandmother of David. A story of gleaning and family care stands inside the story of a kingdom.','RUT 1;RUT 2;RUT 4','moab bethlehem','naomi boaz obed jesse david')
add('hannah','A prayer at Shiloh','land','person','Hannah brings her grief to the sanctuary at Shiloh. Samuel’s birth and dedication lead into a song about reversals: strength and weakness, hunger and fullness, humiliation and honor. Her family story opens the book that will trace Israel’s transition to monarchy.','1SA 1;1SA 2','shiloh','samuel ark-captured')
add('ark-captured','The ark leaves Shiloh’s world','land','story','Israel takes the ark into battle, but the army is defeated and the ark captured. The Philistine episodes that follow overturn the assumption that possessing a sacred object means controlling its power. The ark’s later journey to Jerusalem will carry the memory of these events.','1SA 4;1SA 5;1SA 6','shiloh','samuel tabernacle ark-jerusalem')
add('samuel','Samuel and the demand for a king','land','prophet','Called as a child in Eli’s household, Samuel becomes a prophet and judge during a changing political world. When the people demand a king, he warns about royal power and then participates in the anointing of Saul and David. He connects the age of judges with the monarchy.','1SA 3;1SA 8;1SA 10;1SA 16','shiloh mizpah bethlehem','hannah saul david')

add('goliath','David in the Valley of Elah','united','battle','A shepherd enters a military standoff and confronts Goliath with a sling. The chapter contrasts armor, reputation, and confidence in God. It also introduces the public consequences of David’s courage: his place in Saul’s household and his growing reputation become central to the conflict that follows.','1SA 17','elah','david saul jonathan')
add('gilboa-battle','The fall of Saul’s house','united','battle','The battle on Gilboa brings the deaths of Saul and Jonathan. David’s lament refuses to reduce their deaths to political convenience. The transition is not immediate or uncontested: Saul’s son Ish-bosheth also rules before David becomes king over all Israel.','1SA 31;2SA 1;2SA 2','gilboa','saul jonathan david ishbosheth')
add('david-jerusalem','David takes Jerusalem','united','story','David first rules from Hebron. After the tribes recognize him, Jerusalem becomes his capital. The city’s political importance grows alongside its religious importance, binding the royal household and the future temple to the same place.','2SA 5','hebron jerusalem','david ark-jerusalem covenant-david')
add('ark-jerusalem','The ark comes to Jerusalem','united','story','Bringing the ark to Jerusalem involves celebration, death, fear, and a renewed attempt. David dances, while Michal’s response exposes tension inside the royal household. The story connects the portable sanctuary of Exodus with the city that will become the center of temple worship.','2SA 6;1CH 15;1CH 16','jerusalem','david michal tabernacle temple')
add('covenant-david','A house and a promise','united','story','David wants to build a house for God, but Nathan delivers a promise about David’s own house—his dynasty. The passage links kingship, succession, discipline, and enduring mercy. It becomes an important thread for understanding both royal hope and the crisis of exile.','2SA 7;1CH 17','jerusalem','david nathan solomon jehoiachin-release')
add('david-bathsheba','Nathan confronts the king','united','story','David takes Bathsheba and arranges the death of her husband Uriah. Nathan’s parable exposes the king’s wrongdoing. The account refuses to shield a celebrated king from moral judgment, and the consequences move through the subsequent history of David’s household.','2SA 11;2SA 12','jerusalem','david bathsheba nathan absalom solomon')
add('absalom','A son’s revolt','united','person','Absalom’s story emerges from violence and failed justice within David’s family. He wins support, drives David from Jerusalem, and dies during the ensuing conflict. David’s grief makes the political struggle painfully personal: the rival claimant is still his son.','2SA 13;2SA 15;2SA 18','jerusalem','david david-bathsheba solomon')
add('temple','Solomon’s temple','united','story','The temple draws together royal ambition, skilled labor, international cooperation, and worship. Solomon’s dedication asks whether God can truly be contained in a building and includes prayer for a future people in exile. Read that prayer beside the temple’s destruction to see how Kings connects its beginning and ending.','1KI 5;1KI 6;1KI 8','jerusalem','solomon tabernacle ark-jerusalem jerusalem-falls')
add('queen-sheba','A queen comes with questions','united','person','The queen of Sheba comes to test Solomon with difficult questions and sees his wisdom and royal splendor. Kings and Chronicles tell this visit briefly. The later Ethiopian Kebra Nagast develops a much larger account; it is a distinct work, not a chapter of Kings or a book that this atlas silently folds into the biblical canon.','1KI 10:1-13;2CH 9:1-12','jerusalem','solomon temple',note='The identification of Sheba and the later Ethiopian royal tradition deserve separate treatment. The visitor’s personal name is not given in Kings.')
add('kingdom-split','One kingdom becomes two','divided','story','At Shechem, Rehoboam refuses the request to ease the burden imposed under Solomon. The northern tribes turn to Jeroboam, while Rehoboam retains Judah. From here, the reader has to follow two royal histories at once. The kings view makes that parallel story visible.','1KI 11;1KI 12','shechem jerusalem bethel','solomon rehoboam jeroboam-1 ahijah',date='Conventionally c. 931 BCE',bce=931)
add('ahijah','Ahijah’s torn cloak','divided','prophet','Ahijah of Shiloh meets Jeroboam and tears a new garment into twelve pieces, giving him ten. The symbolic act announces a division of Solomon’s kingdom while also placing conditions on Jeroboam’s rule. Later, the same prophet brings judgment on Jeroboam’s household.','1KI 11:29-39;1KI 14','shiloh','kingdom-split jeroboam-1 solomon')
add('elijah','Elijah enters the story','divided','prophet','Elijah announces drought in Ahab’s reign, is sustained in unexpected places, and encounters a widow at Zarephath. His ministry confronts royal power and competing worship, but also includes exhaustion and the need for renewal. He belongs in the same historical view as Ahab, Jezebel, and Jehoshaphat.','1KI 17;1KI 19','zarephath carmel','ahab jezebel carmel-contest naboth elisha',date='Ninth century BCE; ministries not precisely dated')
add('carmel-contest','The confrontation on Carmel','divided','story','Elijah gathers the people on Carmel and challenges their divided allegiance. The contest with the prophets of Baal leads to fire, judgment, and rain after drought. The following chapter’s flight and despair are part of the same prophet’s story; the mountaintop victory is not the end of it.','1KI 18;1KI 19','carmel','elijah ahab jezebel')
add('naboth','A vineyard and a king’s appetite','divided','story','Naboth refuses to surrender his ancestral inheritance to Ahab. Jezebel arranges accusations and his death, after which Ahab takes the vineyard. Elijah confronts the king. This story connects land, inheritance, false testimony, and royal abuse of power in a single household’s loss.','1KI 21','jezreel','ahab jezebel elijah jehu-revolt')
add('ramoth-battle','Two kings at Ramoth-gilead','divided','battle','Ahab of Israel and Jehoshaphat of Judah join in battle against Aram. Micaiah’s warning stands against the favorable message of the other prophets. Ahab goes disguised, is struck by an arrow, and dies. This is a clear point where the histories of the two kingdoms meet.','1KI 22;2CH 18','ramoth samaria','ahab jehoshaphat micaiah',date='Conventionally c. 853 BCE',bce=853)
add('micaiah','Micaiah refuses the easy answer','divided','prophet','Asked to join the reassuring voices before battle, Micaiah insists on speaking what he is given. His vision of the heavenly council and his warning about the scattered people form the theological center of the Ramoth-gilead episode. His message is rejected, but Kings then narrates Ahab’s death.','1KI 22:5-28','samaria ramoth','ahab jehoshaphat ramoth-battle heavenly-court')
add('elisha','Elisha takes up the mantle','divided','prophet','Elisha follows Elijah and receives his mantle after the departure at the Jordan. His stories move through households, famine, healing, war, and royal succession. The succession is prophetic, not a father-to-son dynasty; the family view does not turn it into one.','2KI 2;2KI 4;2KI 8','jordan samaria damascus','elijah naaman jehu-revolt joram-israel')
add('naaman','A commander washes in the Jordan','divided','person','An unnamed captive girl points Naaman, an Aramean commander, toward help in Israel. Elisha’s instructions disappoint him, but his servants persuade him to wash in the Jordan. Healing crosses the boundary between rival peoples, and the chapter ends by turning its scrutiny toward Gehazi’s greed.','2KI 5','damascus jordan','elisha joram-israel')
add('jehu-revolt','The house of Ahab falls','divided','story','An anointing sets Jehu’s revolt in motion. Joram of Israel, Ahaziah of Judah, and Jezebel die as the coup unfolds, followed by the destruction of Ahab’s house. Kings and Hosea do not offer a simple, identical appraisal of the violence. Their different emphases should remain visible.','2KI 9;2KI 10;HOS 1:4-5','ramoth jezreel samaria','jehu joram-israel ahaziah-judah jezebel athaliah hosea',date='Conventionally c. 841 BCE',bce=841)
add('jonah','Jonah and the enemy city','divided','prophet','The book of Jonah tells of flight, a great fish, a commission to Nineveh, and a prophet angry at mercy. Separately, 2 Kings 14 names Jonah son of Amittai in the time of Jeroboam II. The narrative’s Assyrian king is unnamed, so this atlas does not assign the Nineveh episode an exact year.','JON 1;JON 3;JON 4;2KI 14:23-27','nineveh','jeroboam-2 nahum',note='The time of Jonah’s ministry, the setting of the narrative, and the book’s composition are separate questions.')
add('amos','Justice at the royal sanctuary','divided','prophet','Amos speaks against exploitation, complacency, and worship detached from justice. The book places his words in the reigns of Uzziah of Judah and Jeroboam II of Israel. His confrontation with Amaziah at Bethel lets us watch a prophet challenge the assumptions of a royal sanctuary.','AMO 1:1;AMO 5;AMO 7','bethel','jeroboam-2 uzziah hosea')
add('hosea','Covenant and unfaithfulness','divided','prophet','Hosea’s family imagery and prophetic speeches expose the northern kingdom’s unfaithfulness while returning again to divine compassion. Its opening names kings in both Judah and Israel. The book’s mention of the bloodshed at Jezreel invites comparison with the account of Jehu in Kings.','HOS 1;HOS 2;HOS 11','jezreel samaria','jehu-revolt jeroboam-2 fall-samaria')
add('isaiah','A vision and a kingdom in danger','divided','prophet','Isaiah’s call is set in the year of Uzziah’s death. His ministry intersects the reigns of Jotham, Ahaz, and Hezekiah as Assyrian power grows. The book connects the holiness of God with the public life of a threatened kingdom. Its later chapters also speak into exile and hope; they are not all pinned to one moment.','ISA 1:1;ISA 6;ISA 7;ISA 36','jerusalem','uzziah ahaz hezekiah assyrian-siege heavenly-court')
add('micah','What does the Lord require?','divided','prophet','Micah addresses Samaria and Jerusalem during the reigns named in his opening: Jotham, Ahaz, and Hezekiah. His words move from judgment against predatory power to hope for restoration. Jeremiah later remembers Micah’s warning as an example of prophetic speech heard in Hezekiah’s time.','MIC 1:1;MIC 3;MIC 6:6-8;JER 26:18-19','samaria jerusalem','isaiah hezekiah jeremiah')
add('fall-samaria','The northern kingdom falls','divided','battle','The Assyrian siege of Samaria ends the northern monarchy. 2 Kings 17 recounts Hoshea’s rebellion and the fall, then offers a long theological explanation of exile. The population movements that follow change the land’s political and religious landscape. Judah continues, but the two-kingdom story is no longer symmetrical.','2KI 17;2KI 18:9-12','samaria','hoshea hosea hezekiah assyrian-siege',date='c. 722/721 BCE',bce=722)

add('assyrian-siege','Jerusalem under threat','exile','battle','After the fall of the northern kingdom, Sennacherib’s forces threaten Judah. Lachish and Jerusalem become centers of the crisis, while Isaiah addresses Hezekiah. Kings, Isaiah, and Chronicles preserve accounts with different emphases. Assyrian evidence also records the campaign; the atlas’s date is the conventional 701 BCE anchor.','2KI 18;2KI 19;ISA 36;ISA 37;2CH 32','lachish jerusalem','hezekiah isaiah micah fall-samaria',date='701 BCE',bce=701)
add('manasseh-prayer','Manasseh and the possibility of return','exile','story','Kings emphasizes Manasseh’s wrongdoing and its consequences. Chronicles also tells of his captivity, humbling, and return. The Prayer of Manasseh gives voice to repentance in a distinct transmitted prayer; it should not be presented as a quotation found inside Kings. Reading these sources together reveals their different portraits.','2KI 21;2CH 33;MAN 1','jerusalem','manasseh josiah',note='The Prayer of Manasseh is a separate work associated with the king, not a passage embedded in 2 Kings.')
add('lost-scroll','A scroll is found','exile','story','During repairs to the temple, a book of the law is found and read to Josiah. Huldah interprets the situation, and the king leads a public covenant renewal and reform. The narrative joins a recovered text with renewed responsibility; hearing and responding are inseparable.','2KI 22;2KI 23;2CH 34','jerusalem','josiah huldah jeremiah temple',date='Josiah’s eighteenth year; conventionally c. 622 BCE',bce=622)
add('huldah','The prophet consulted by the king','exile','prophet','When Josiah’s officials seek a word about the discovered scroll, they go to Huldah in Jerusalem. Her answer combines judgment on the kingdom with a word concerning the king’s response. She belongs at the center of this episode of reform, not at its margins.','2KI 22:11-20;2CH 34:22-28','jerusalem','josiah lost-scroll')
add('nahum','The fall of Nineveh envisioned','exile','prophet','Nahum addresses Nineveh with language of judgment against a violent imperial power. Read alongside Jonah, the same city becomes a place where different prophetic books explore mercy, repentance, oppression, and judgment. The precise date of Nahum’s ministry is uncertain; Nineveh’s historical fall is conventionally dated to 612 BCE.','NAM 1;NAM 2;NAM 3','nineveh','jonah assyrian-siege',note='A prophet’s oracle is not automatically a dated eyewitness report of the city’s fall.')
add('zephaniah','A warning in Josiah’s reign','exile','prophet','Zephaniah’s opening places his prophecy in the reign of Josiah. Judgment reaches Judah and surrounding peoples, but the book also speaks of a humble remnant and restoration. Its royal setting is explicit even though the exact years of the prophet’s ministry are not.','ZEP 1;ZEP 3','jerusalem','josiah jeremiah')
add('megiddo-battle','Josiah meets Pharaoh Neco','exile','battle','Josiah’s reign ends when he meets Pharaoh Neco at Megiddo. Kings gives a brief account; Chronicles adds a fuller scene and a warning Josiah does not heed. His death changes the political situation of Judah as Egypt and Babylon struggle for influence.','2KI 23:28-30;2CH 35:20-27','megiddo','josiah jehoahaz-judah jehoiakim',date='609 BCE',bce=609)
add('jeremiah','A prophet through the collapse','exile','prophet','Jeremiah’s ministry begins in Josiah’s time and continues into the catastrophe of Jerusalem. His messages confront false reassurance, injustice, and the temptation to treat the temple as a guarantee. The book also preserves promises of restoration and a new covenant amid judgment.','JER 1;JER 7;JER 31;JER 39','jerusalem mizpah','josiah jehoiakim zedekiah jerusalem-falls gedaliah')
add('habakkuk','How long?','exile','prophet','Habakkuk argues with God about violence and the rise of the Chaldeans. The book does not name a reigning Judahite king, so its location near the Babylonian crisis is a broad setting rather than a precise date. Complaint, waiting, and trust belong together in this prophetic conversation.','HAB 1;HAB 2;HAB 3',links='jeremiah jerusalem-falls',note='Placed broadly near the rise of Babylon; the book itself does not provide a regnal date.')
add('first-exile','A king carried to Babylon','exile','story','Jehoiachin’s surrender is followed by deportation of royal officials, warriors, craftspeople, and treasures. Nebuchadnezzar installs Zedekiah. The story does not end with this first capture: a further rebellion and a more devastating siege lie ahead. Ezekiel’s prophetic setting is among the exiles.','2KI 24:8-20;EZK 1:1-3','jerusalem babylon','jehoiachin zedekiah ezekiel jerusalem-falls',date='597 BCE',bce=597)
add('ezekiel','Visions among the exiles','exile','prophet','Ezekiel’s opening vision is set among the exiles by the river Chebar, in the fifth year of Jehoiachin’s exile. His enacted signs, visions, and promises of restoration address people far from Jerusalem. The precise Chebar location is not mapped here; the Babylon marker provides regional orientation.','EZK 1;EZK 10;EZK 37','babylon','jehoiachin first-exile heavenly-court jerusalem-falls')
add('jerusalem-falls','Jerusalem and the temple burn','exile','battle','Zedekiah’s rebellion leads to siege, famine, capture, and the destruction of Jerusalem’s temple. The objects, buildings, and royal hopes that occupied earlier chapters of Kings are dismantled. Jeremiah 52 offers a parallel account. The event is commonly dated to 587 or 586 BCE; the atlas uses the latter as its display convention.','2KI 25:1-21;JER 39;JER 52','jerusalem babylon','zedekiah jeremiah temple gedaliah jehoiachin-release',date='587/586 BCE (display: 586)',bce=586)
add('gedaliah','A fragile life after the siege','exile','person','Gedaliah is appointed over the people remaining in Judah and is based at Mizpah. His assassination destroys a fragile attempt at stability, and fear leads survivors toward Egypt. The aftermath of a city’s fall is its own human story, not simply the empty space after a royal timeline ends.','2KI 25:22-26;JER 40;JER 41','mizpah egypt','jeremiah jerusalem-falls')
add('jehoiachin-release','A seat at the king’s table','exile','story','Kings ends with an unexpected change of scene. Jehoiachin is released from prison in Babylon and receives provision at the royal table. The land and temple have not been restored, but the narrative leaves a surviving member of David’s house alive. It is an ending that invites the reader to keep following the promise.','2KI 25:27-30;JER 52:31-34','babylon','jehoiachin covenant-david jerusalem-falls',date='c. 562/561 BCE',bce=561)

# Named people used in the genealogies and connection panels.
def person(id,title,era,summary,reference,loc='',links=''):
    add(id,title,era,'person',summary,reference,loc,links,primary=False)

person('adam','Adam','beginnings','The first human in the garden account and the starting point of the genealogy traced through Seth to Noah. Genesis 4 also preserves a separate line through Cain.','GEN 2;GEN 4;GEN 5',links='eve cain-abel enoch')
person('eve','Eve','beginnings','Named as the mother of all living in Genesis, Eve belongs to both the garden story and the painful family story that follows it.','GEN 2;GEN 3;GEN 4',links='adam eden cain-abel')
for id,title,reference,summary in [
('seth','Seth','GEN 4:25-26;GEN 5:3-8','A son of Adam and Eve, named after Abel’s death; the genealogy of Genesis 5 continues through his line.'),
('enosh','Enosh','GEN 5:6-11','Son of Seth and father of Kenan in the genealogy of Genesis 5.'),
('kenan','Kenan','GEN 5:9-14','Son of Enosh and father of Mahalalel in the Genesis 5 genealogy.'),
('mahalalel','Mahalalel','GEN 5:12-17','Son of Kenan and father of Jared in the Genesis 5 genealogy.'),
('jared','Jared','GEN 5:15-20','Father of Enoch. 1 Enoch 6 places the descent of the Watchers in the days of Jared.'),
('methuselah','Methuselah','GEN 5:21-27;ENO 106','Son of Enoch and father of Lamech; in 1 Enoch 106 he seeks an explanation of Noah’s extraordinary birth.'),
('lamech','Lamech, Noah’s father','GEN 5:25-31;ENO 106','Noah’s father in Seth’s line. He must not be confused with the Lamech in Cain’s genealogy in Genesis 4.'),
('shem','Shem','GEN 9:18-29;GEN 10;GEN 11:10-26','A son of Noah; the genealogical line toward Terah and Abraham is traced through Shem.'),
('ham','Ham','GEN 9:18-29;GEN 10','A son of Noah named in the post-Flood family stories and the table of nations.'),
('japheth','Japheth','GEN 9:18-29;GEN 10','A son of Noah whose descendants appear in the table of nations.')]: person(id,title,'beginnings',summary,reference)
person('terah','Terah','patriarchs','Father of Abram, Nahor, and Haran. Genesis describes the household moving from Ur toward Canaan and settling in Haran.','GEN 11:24-32','ur haran','abraham fire-idols')
person('abraham','Abraham / Abram','patriarchs','Called out of his homeland, Abraham receives promises of descendants, land, and blessing. His story includes courage, hospitality, uncertainty, and failures; Genesis and Jubilees supply related but distinct accounts.','GEN 12;GEN 15;GEN 17;JUB 12','ur haran hebron beersheba','sarah hagar ishmael isaac abraham-call offering-isaac')
person('sarah','Sarah / Sarai','patriarchs','Abraham’s wife and Isaac’s mother. Her story carries the long wait for a child, laughter at an extraordinary promise, and conflict concerning Hagar and Ishmael.','GEN 16;GEN 17;GEN 18;GEN 21','hebron','abraham isaac hagar')
person('hagar','Hagar','patriarchs','An Egyptian woman in Sarah’s household and the mother of Ishmael. Her encounters in the wilderness give a powerful place to a person at risk of being overlooked within the ancestral story.','GEN 16;GEN 21','beersheba','sarah abraham ishmael')
person('ishmael','Ishmael','patriarchs','Son of Abraham and Hagar. Genesis gives him a promise of descendants and preserves his genealogy alongside the line through Isaac.','GEN 16;GEN 21;GEN 25:12-18',links='abraham hagar isaac')
person('isaac','Isaac','patriarchs','Son of Abraham and Sarah, husband of Rebekah, and father of Esau and Jacob. His story includes the test on the mountain and the struggle over the family blessing.','GEN 21;GEN 22;GEN 24;GEN 27','beersheba','abraham sarah rebekah jacob esau')
person('rebekah','Rebekah','patriarchs','Wife of Isaac and mother of Esau and Jacob. Her decisive actions connect the marriage story of Genesis 24 with the contested blessing in Genesis 27.','GEN 24;GEN 25;GEN 27',links='isaac esau jacob')
person('lot','Lot','patriarchs','Son of Haran and nephew of Abraham. His separation from Abraham and life near Sodom connect the ancestral family with the cities of the plain.','GEN 11:27;GEN 13;GEN 19',links='abraham sodom')
person('esau','Esau / Edom','patriarchs','Isaac and Rebekah’s elder son, Jacob’s twin. Conflict over birthright and blessing eventually gives way to a meeting marked by fear and reconciliation.','GEN 25;GEN 27;GEN 33;GEN 36',links='isaac rebekah jacob jacob-wrestles')
person('jacob','Jacob / Israel','patriarchs','Son of Isaac and Rebekah. The ancestral story follows him through deception, exile, marriages, wrestling, reconciliation, and grief before the family’s move to Egypt.','GEN 25;GEN 28;GEN 32;GEN 46','bethel haran jabbok egypt','isaac rebekah esau leah rachel twelve-tribes')
person('leah','Leah','patriarchs','Daughter of Laban and wife of Jacob. Genesis names six sons and Dinah among her children; Judah’s and Levi’s lines become particularly important later.','GEN 29;GEN 30;GEN 35:23',links='jacob rachel judah levi dinah')
person('rachel','Rachel','patriarchs','Daughter of Laban, wife of Jacob, and mother of Joseph and Benjamin. Her long desire for children and death after Benjamin’s birth shape the family’s story.','GEN 29;GEN 30;GEN 35:16-20',links='jacob leah joseph benjamin')
person('bilhah','Bilhah','patriarchs','Rachel’s servant, given to Jacob; mother of Dan and Naphtali in Genesis’s account of the household.','GEN 30:1-8;GEN 35:25',links='jacob dan naphtali')
person('zilpah','Zilpah','patriarchs','Leah’s servant, given to Jacob; mother of Gad and Asher.','GEN 30:9-13;GEN 35:26',links='jacob gad asher')
person('joseph','Joseph','patriarchs','Son of Jacob and Rachel. Sold into Egypt, imprisoned, and elevated to authority, he becomes the means of preserving his family during famine.','GEN 37;GEN 41;GEN 45','egypt','jacob rachel benjamin sold-joseph egypt-family')
for id,title,ref,desc in [
('reuben','Reuben','GEN 29:32;GEN 49:3-4','Firstborn son of Jacob and Leah; his place in the household is revisited in Jacob’s final words.'),
('simeon','Simeon','GEN 29:33;GEN 34','Son of Jacob and Leah, paired with Levi in the violent aftermath of the assault on Dinah.'),
('levi','Levi','GEN 29:34;EXO 6:16-20','Son of Jacob and Leah. The family line of Moses, Aaron, and Miriam is traced through Levi.'),
('judah','Judah','GEN 29:35;GEN 38;GEN 44','Son of Jacob and Leah. His story connects the brothers’ betrayal of Joseph, Tamar, and the later ancestry of David.'),
('issachar','Issachar','GEN 30:17-18','A son of Jacob and Leah, named in the family list that underlies the tribal traditions.'),
('zebulun','Zebulun','GEN 30:19-20','A son of Jacob and Leah, named in the family list that underlies the tribal traditions.'),
('dinah','Dinah','GEN 30:21;GEN 34','Daughter of Jacob and Leah. Genesis 34 tells of the violence against her and the destructive response of her brothers.'),
('dan','Dan','GEN 30:1-6','Son of Jacob and Bilhah; the name is also used for a tribe and, later, a northern city.'),
('naphtali','Naphtali','GEN 30:7-8','Son of Jacob and Bilhah, an ancestor named in the tribal traditions.'),
('gad','Gad','GEN 30:9-11','Son of Jacob and Zilpah, an ancestor named in the tribal traditions.'),
('asher','Asher','GEN 30:12-13','Son of Jacob and Zilpah, an ancestor named in the tribal traditions.'),
('benjamin','Benjamin','GEN 35:16-20;GEN 44','Son of Jacob and Rachel. His mother dies after his birth; his safety later becomes central to Joseph’s testing of the brothers.'),
('tamar','Tamar','GEN 38','The woman who challenges Judah’s failure to provide for her future. She becomes the mother of Perez and Zerah.'),
('perez','Perez','GEN 38:27-30;RUT 4:18-22','Son of Judah and Tamar. Ruth 4 traces the family line from Perez to David.')]: person(id,title,'patriarchs',desc,ref)
person('moses','Moses','exodus','Born under an oppressive decree, raised in Pharaoh’s household, and called in the wilderness, Moses becomes the leader of the Exodus and mediator of the covenant. Jubilees frames its revelation as given to him at Sinai.','EXO 2;EXO 3;DEU 34;JUB 1','egypt sinai nebo','aaron miriam burning-bush jubilees-sinai')
person('aaron','Aaron','exodus','Moses’s brother and spokesman, later central to the priestly service. His story includes both consecration and responsibility in the golden-calf episode.','EXO 4:14-16;EXO 6:20;EXO 28;EXO 32',links='moses miriam golden-calf')
person('miriam','Miriam','exodus','A prophet associated with the song after the sea crossing and named alongside Moses and Aaron in Israel’s memory of deliverance. Numbers also preserves her conflict with Moses.','EXO 15:20-21;NUM 12;MIC 6:4',links='moses aaron sea-crossing')
person('joshua','Joshua','land','Moses’s successor leads the people across the Jordan and is central to the narratives of entry, allotment, and covenant renewal in the land.','NUM 27:18-23;JOS 1;JOS 24','jordan jericho shechem','moses jordan-crossing jericho-battle shechem-covenant')
person('rahab','Rahab','land','A woman of Jericho who shelters the spies and asks protection for her family. Joshua describes her household’s rescue when the city falls.','JOS 2;JOS 6:22-25','jericho','joshua jericho-battle')
person('naomi','Naomi','land','Widowed in Moab, Naomi returns to Bethlehem with Ruth. Her movement from loss toward a renewed household shapes the book of Ruth.','RUT 1;RUT 4','moab bethlehem','ruth boaz obed')
person('boaz','Boaz','land','A relative of Naomi’s husband and a landowner at Bethlehem. His protection of Ruth and public act of family redemption connect everyday generosity with David’s ancestry.','RUT 2;RUT 3;RUT 4','bethlehem','ruth obed')
person('obed','Obed','land','Son of Ruth and Boaz, father of Jesse, and grandfather of David according to Ruth’s closing genealogy.','RUT 4:13-22',links='ruth boaz jesse david')
person('jesse','Jesse','united','Father of David, living at Bethlehem when Samuel comes to anoint a king.','1SA 16;RUT 4:17-22','bethlehem','obed david')
person('jonathan','Jonathan','united','Son of Saul and close friend of David. His loyalty to David exists alongside his place in Saul’s royal household; he dies with Saul at Gilboa.','1SA 14;1SA 18;1SA 20;1SA 31','gilboa','saul david gilboa-battle')
person('michal','Michal','united','Saul’s daughter and David’s wife. She helps David escape Saul, and later confronts him after the ark’s entry into Jerusalem.','1SA 18:20-29;1SA 19:11-17;2SA 6:16-23',links='saul david ark-jerusalem')
person('ishbosheth','Ish-bosheth','united','Saul’s son who is made king by Abner after Saul’s death. His rule overlaps David’s early reign at Hebron; the atlas does not pretend the transition was uncontested.','2SA 2:8-11;2SA 4',links='saul david gilboa-battle')
person('bathsheba','Bathsheba','united','Wife of Uriah, later David’s wife and Solomon’s mother. Her story belongs both to David’s grave wrongdoing and to the struggle over royal succession.','2SA 11;2SA 12;1KI 1','jerusalem','david david-bathsheba solomon')
add('nathan','Nathan speaks to David','united','prophet','Nathan delivers the promise concerning David’s house, confronts David after the death of Uriah, and acts during the dispute over Solomon’s succession. His role shows a prophet speaking both promise and correction to the same king.','2SA 7;2SA 12;1KI 1','jerusalem','david covenant-david david-bathsheba solomon')
person('jezebel','Jezebel','divided','Daughter of Ethbaal, king of the Sidonians, and wife of Ahab. Kings connects her with persecution of prophets, the death of Naboth, and the violent fall of Ahab’s house.','1KI 16:31;1KI 18;1KI 21;2KI 9','sidon jezreel','ahab elijah naboth jehu-revolt')

# Reign bars use the Thiele column in the cited comparison table as a coherent
# display convention (not a new reconciliation of all regnal totals). Very short
# reigns receive a one-year plotting interval, with their actual duration noted.
rulers = [
('saul','Saul','united',1050,1010,'1SA 9;1SA 10;1SA 15;1SA 31','Israel’s first king in Samuel’s narrative. His story moves from anointing and military success to disobedience, conflict with David, and death at Gilboa.','samuel david jonathan gilboa-battle'),
('david','David','united',1010,970,'1SA 16;2SA 5;2SA 7;2SA 11','Shepherd, fugitive, and king. David makes Jerusalem his capital and receives a dynastic promise, but the books of Samuel also preserve his serious failures and the suffering within his household.','saul solomon goliath covenant-david david-bathsheba'),
('solomon','Solomon','united',970,931,'1KI 1;1KI 3;1KI 8;1KI 11','David and Bathsheba’s son, associated with wisdom and the temple. Kings also describes burdensome rule and divided loyalties that prepare the way for the kingdom’s fracture.','david bathsheba temple queen-sheba rehoboam'),
('jeroboam-1','Jeroboam I','israel',931,910,'1KI 11;1KI 12;1KI 14','The first king of the northern kingdom. His sanctuaries at Bethel and Dan become a repeated point of judgment in the books of Kings.','rehoboam ahijah golden-calf jacob-bethel'),
('nadab','Nadab','israel',910,909,'1KI 15:25-31','Jeroboam’s son. Baasha kills him during a siege and brings Jeroboam’s royal house to an end.','jeroboam-1 baasha'),
('baasha','Baasha','israel',909,886,'1KI 15:27-34;1KI 16:1-7','His coup ends Jeroboam’s dynasty, but Kings judges his own rule by the same pattern of wrongdoing. He also conflicts with Asa of Judah.','nadab elah asa'),
('elah','Elah','israel',886,885,'1KI 16:8-14','Baasha’s son, killed by Zimri while drinking at Tirzah. His short reign ends another northern dynasty.','baasha zimri'),
('zimri','Zimri','israel',885,885,'1KI 16:9-20','His coup is followed by only seven days of rule at Tirzah. The army makes Omri king, and Zimri dies when the palace burns.','elah omri'),
('tibni','Tibni, rival claimant','israel',885,880,'1KI 16:21-22','A portion of the people supports Tibni while another supports Omri. He is shown as a rival claimant, not as an uncontested successor between Zimri and Omri.','zimri omri'),
('omri','Omri','israel',885,874,'1KI 16:15-28','After civil conflict, Omri establishes his rule and builds Samaria as the northern capital. His dynasty continues through Ahab.','tibni ahab'),
('ahab','Ahab','israel',874,853,'1KI 16:29-34;1KI 18;1KI 21;1KI 22','Son of Omri and husband of Jezebel. Elijah’s confrontations, Naboth’s vineyard, and the alliance with Jehoshaphat all meet within his reign.','omri jezebel elijah jehoshaphat naboth ramoth-battle'),
('ahaziah-israel','Ahaziah of Israel','israel',853,852,'1KI 22:51-53;2KI 1','Ahab’s son. His appeal to Baal-zebub after an injury brings a confrontation with Elijah. Do not confuse him with the later Ahaziah of Judah.','ahab elijah joram-israel'),
('joram-israel','Joram / Jehoram of Israel','israel',852,841,'2KI 3;2KI 9','Ahab’s son, ruling during Elisha’s ministry. His alliance with Ahaziah of Judah ends in Jehu’s revolt. Another Jehoram rules Judah during part of the same era.','elisha ahaziah-judah jehu-revolt'),
('jehu','Jehu','israel',841,814,'2KI 9;2KI 10','An anointed commander whose revolt destroys Ahab’s house. Compare Kings’s account with Hosea’s later reference to the bloodshed of Jezreel.','jehu-revolt hosea jehoahaz-israel'),
('jehoahaz-israel','Jehoahaz of Israel','israel',814,798,'2KI 13:1-9','Jehu’s son, whose kingdom suffers under Aramean pressure. Kings describes both his appeal for help and the continuing religious failures of the kingdom.','jehu joash-israel elisha'),
('joash-israel','Jehoash / Joash of Israel','israel',798,782,'2KI 13:10-25;2KI 14:8-16','He visits the dying Elisha and later defeats Amaziah of Judah. His name is easily confused with Joash of Judah, so the atlas always supplies the kingdom.','elisha amaziah jeroboam-2'),
('jeroboam-2','Jeroboam II','israel',782,753,'2KI 14:23-29;AMO 1:1;HOS 1:1','A period of northern expansion, also the royal setting named by Amos and Hosea. Kings connects a prophecy of Jonah son of Amittai with the restoration of territory.','amos hosea jonah uzziah'),
('zechariah-king','Zechariah of Israel','israel',753,753,'2KI 15:8-12','Jeroboam II’s son, ruling for six months before Shallum’s coup. His death ends Jehu’s dynasty. This is not the later prophet Zechariah.','jeroboam-2 shallum'),
('shallum','Shallum','israel',752,752,'2KI 15:10-15','His coup gives him a month of rule in Samaria before Menahem kills him. Short reigns are shown as small markers rather than fabricated full-year reigns.','zechariah-king menahem'),
('menahem','Menahem','israel',752,742,'2KI 15:14-22','He takes the throne by violence and pays tribute to the Assyrian king Pul to strengthen his rule. Northern politics are increasingly entangled with imperial power.','shallum pekahiah'),
('pekahiah','Pekahiah','israel',742,740,'2KI 15:23-26','Menahem’s son, killed by Pekah in a palace conspiracy at Samaria.','menahem pekah'),
('pekah','Pekah','israel',740,732,'2KI 15:27-31;2KI 16;ISA 7','He joins Rezin of Aram against Judah while Assyria takes northern territory. His reported twenty years require chronological reconstruction; this display uses the comparison table’s sole-rule convention.','ahaz isaiah hoshea'),
('hoshea','Hoshea','israel',732,722,'2KI 15:30;2KI 17','The northern kingdom’s last king. Rebellion against Assyria leads to imprisonment and the siege of Samaria.','pekah fall-samaria'),
('rehoboam','Rehoboam','judah',931,913,'1KI 12;1KI 14:21-31','Solomon’s son. His answer to the request for relief precipitates the split, and his reign faces invasion by Shishak of Egypt.','solomon kingdom-split jeroboam-1 abijah'),
('abijah','Abijah / Abijam','judah',913,911,'1KI 15:1-8;2CH 13','Rehoboam’s son. Kings and Chronicles give different amounts of attention to his short reign and the conflict with the north.','rehoboam asa'),
('asa','Asa','judah',911,870,'1KI 15:9-24;2CH 14;2CH 16','A reforming king who removes idols, yet later turns to an alliance with Aram against Baasha. Chronicles preserves prophetic criticism of that choice.','abijah baasha jehoshaphat'),
('jehoshaphat','Jehoshaphat','judah',870,848,'1KI 22;2CH 17;2CH 18','He rules Judah alongside Ahab in Israel and joins him at Ramoth-gilead. Chronicles expands the portrait with teaching, reform, and further alliances.','asa ahab ramoth-battle jehoram-judah'),
('jehoram-judah','Jehoram of Judah','judah',848,841,'2KI 8:16-24;2CH 21','Jehoshaphat’s son, married into Ahab’s house. Kings connects his reign with Edom’s revolt. He is distinct from the contemporary Joram of Israel.','jehoshaphat athaliah ahaziah-judah joram-israel'),
('ahaziah-judah','Ahaziah of Judah','judah',841,841,'2KI 8:25-29;2KI 9:27-29','Son of Jehoram and Athaliah. He joins Joram of Israel and is caught in Jehu’s revolt. His short reign creates a succession crisis in Judah.','jehoram-judah athaliah jehu-revolt'),
('athaliah','Athaliah','judah',841,835,'2KI 11;2CH 22;2CH 23','After her son Ahaziah’s death, Athaliah seizes power. Joash is hidden, and a later alliance around the priest Jehoiada brings her rule to an end. Her exact placement within Omri’s family is described with different kinship wording in Kings.','ahaziah-judah joash-judah jehu-revolt'),
('joash-judah','Joash / Jehoash of Judah','judah',835,796,'2KI 11;2KI 12;2CH 24','Hidden as a child, crowned after Athaliah’s overthrow, and associated with temple repairs. Chronicles tells a darker later story after Jehoiada’s death.','athaliah ahaziah-judah amaziah temple'),
('amaziah','Amaziah','judah',796,767,'2KI 14;2CH 25','Son of Joash. After victory over Edom, he challenges Jehoash of Israel and suffers defeat and the plundering of Jerusalem.','joash-judah joash-israel uzziah'),
('uzziah','Uzziah / Azariah','judah',767,740,'2KI 15:1-7;2CH 26;ISA 6:1','A long reign associated with strength and a later affliction. The year of his death provides the setting of Isaiah’s throne vision. Co-regencies affect attempts to reconstruct the full chronology.','amaziah jotham isaiah amos'),
('jotham','Jotham','judah',740,732,'2KI 15:32-38;2CH 27;MIC 1:1','Son of Uzziah, active in leadership during his father’s affliction and then king. His era is named in the openings of Isaiah and Micah.','uzziah ahaz isaiah micah'),
('ahaz','Ahaz','judah',732,716,'2KI 16;ISA 7','Facing Israel and Aram, Ahaz turns to Assyria for help. Isaiah’s encounter with him belongs to this political crisis.','jotham pekah isaiah hezekiah'),
('hezekiah','Hezekiah','judah',716,687,'2KI 18;2KI 19;2KI 20;2CH 29','A reforming king who faces Sennacherib’s invasion. Isaiah, the threatened city, and later Babylonian visitors connect his reign with both deliverance and the shadow of exile.','ahaz isaiah assyrian-siege manasseh'),
('manasseh','Manasseh','judah',687,643,'2KI 21:1-18;2CH 33','Kings emphasizes wrongdoing and its long consequences; Chronicles adds captivity and repentance. The separately transmitted Prayer of Manasseh belongs to the wider reading tradition.','hezekiah manasseh-prayer amon'),
('amon','Amon','judah',643,641,'2KI 21:19-26;2CH 33:21-25','Manasseh’s son, killed by palace officials after a short reign. The people then make his son Josiah king.','manasseh josiah'),
('josiah','Josiah','judah',641,609,'2KI 22;2KI 23;2CH 34;2CH 35','The discovery of a law book, Huldah’s message, covenant renewal, and Passover mark a major reform. His death at Megiddo opens Judah’s final unstable decades.','amon huldah lost-scroll zephaniah megiddo-battle'),
('jehoahaz-judah','Jehoahaz of Judah','judah',609,609,'2KI 23:30-34','Josiah’s son, chosen after his father’s death but deposed by Pharaoh Neco after three months and taken to Egypt.','josiah jehoiakim'),
('jehoiakim','Jehoiakim','judah',609,598,'2KI 23:34-37;2KI 24:1-7;JER 36','Installed by Neco, he later becomes entangled with Babylon. Jeremiah 36 describes his destruction of a prophetic scroll.','josiah jehoiachin jeremiah'),
('jehoiachin','Jehoiachin / Jeconiah','judah',598,597,'2KI 24:8-17;2KI 25:27-30','He surrenders during the Babylonian capture and is taken into exile. His later release supplies the final scene of Kings.','jehoiakim zedekiah first-exile jehoiachin-release'),
('zedekiah','Zedekiah','judah',597,586,'2KI 24:17-20;2KI 25;JER 39','Installed by Babylon, he rebels and rules through Jerusalem’s final siege. He is Josiah’s son and Jehoiachin’s uncle, not Jehoiachin’s son.','josiah jehoiachin jeremiah jerusalem-falls'),
]
for id,title,realm,start,end,ref,summary,links in rulers:
    era='united' if realm=='united' else ('exile' if start<722 else 'divided')
    date=(f'c. {start}–{end} BCE' if start!=end else f'c. {start} BCE · short reign')
    add(id,title,era,'king',summary,ref,'jerusalem' if realm=='judah' else ('samaria' if realm=='israel' and start<=885 and id!='zimri' else ''),links,date=date,bce=start,primary=False)
    entries[-1]['reign']=dict(realm=realm,start=start,end=end)
    if id in ('saul','david','solomon'):
        entries[-1]['note']='These early-monarchy dates are broad conventional estimates, not a settled archaeological chronology.'

families=[]
def family(id,title,description,nodes,edges,reference):
    families.append(dict(id=id,title=title,description=description,nodes=[dict(id=i,x=x,y=y) for i,x,y in nodes],edges=[dict(source=a,target=b,kind=k) for a,b,k in edges],refs=refs(reference)))
chain=['adam','seth','enosh','kenan','mahalalel','jared','enoch','methuselah','lamech','noah']
family('before-flood','From Adam to Noah','The Sethite genealogy of Genesis 5. Enoch and Lamech here are distinct from their namesakes in Cain’s line. Only this selected line is shown.',[(i,120+(n%5)*210,75+(n//5)*160) for n,i in enumerate(chain)]+[('shem',540,400),('ham',750,400),('japheth',960,400)],[(a,b,'parent') for a,b in zip(chain,chain[1:])]+[('noah',i,'parent') for i in ['shem','ham','japheth']],'GEN 5;GEN 9:18-19')
family('promise','Abraham’s household','A selected family tree: parent–child lines and named marriages. Other children and marriages are not exhaustively represented.',[('terah',540,55),('abraham',430,165),('sarah',650,165),('hagar',180,165),('ishmael',180,295),('isaac',540,295),('rebekah',790,295),('esau',430,435),('jacob',760,435)],[('terah','abraham','parent'),('abraham','sarah','spouse'),('abraham','hagar','spouse'),('abraham','isaac','parent'),('sarah','isaac','parent'),('abraham','ishmael','parent'),('hagar','ishmael','parent'),('isaac','rebekah','spouse'),('isaac','esau','parent'),('rebekah','esau','parent'),('isaac','jacob','parent'),('rebekah','jacob','parent')],'GEN 11;GEN 16;GEN 21;GEN 24;GEN 25')
tribe_nodes=[('jacob',580,45),('leah',210,150),('rachel',540,150),('bilhah',820,150),('zilpah',1070,150)]
tribe_edges=[]
for mom,kids,x in [('leah',['reuben','simeon','levi','judah','issachar','zebulun','dinah'],210),('rachel',['joseph','benjamin'],540),('bilhah',['dan','naphtali'],820),('zilpah',['gad','asher'],1070)]:
    tribe_edges.append(('jacob',mom,'spouse'))
    for n,kid in enumerate(kids):
        tribe_nodes.append((kid,x,260+n*70));tribe_edges.append((mom,kid,'parent'))
family('tribes','The children of Jacob','Children are grouped under their mothers; Jacob is father of each child shown. Dinah is included. Tribal allotment lists can count Joseph through Ephraim and Manasseh.',tribe_nodes,tribe_edges,'GEN 29;GEN 30;GEN 35:16-26;GEN 48')
family('david-line','Ruth to the royal house','Selected generations in David’s family. The dashed line from Perez to Boaz skips generations explicitly listed in Ruth 4; it is not a direct parent–child claim.',[('judah',200,55),('tamar',460,55),('perez',330,155),('boaz',330,265),('ruth',590,265),('obed',460,365),('jesse',460,465),('david',460,565),('bathsheba',730,565),('solomon',590,675),('rehoboam',590,785)],[('judah','perez','parent'),('tamar','perez','parent'),('perez','boaz','descendant'),('boaz','ruth','spouse'),('boaz','obed','parent'),('ruth','obed','parent'),('obed','jesse','parent'),('jesse','david','parent'),('david','bathsheba','spouse'),('david','solomon','parent'),('bathsheba','solomon','parent'),('solomon','rehoboam','parent')],'GEN 38;RUT 4:18-22;2SA 12:24;1KI 14:21')
family('two-houses','Two houses entangled','Ahab’s northern dynasty meets Judah’s royal house through Athaliah. Her link to Ahab/Omri is deliberately not forced into a precise parent–child edge: Kings uses both kinship descriptions.',[('omri',230,65),('ahab',230,175),('jezebel',490,175),('ahaziah-israel',150,315),('joram-israel',430,315),('jehoshaphat',840,65),('jehoram-judah',840,175),('athaliah',1080,175),('ahaziah-judah',960,315),('joash-judah',960,435)],[('omri','ahab','parent'),('ahab','jezebel','spouse'),('ahab','ahaziah-israel','parent'),('jezebel','ahaziah-israel','parent'),('ahab','joram-israel','parent'),('jehoshaphat','jehoram-judah','parent'),('jehoram-judah','athaliah','spouse'),('jehoram-judah','ahaziah-judah','parent'),('athaliah','ahaziah-judah','parent'),('ahaziah-judah','joash-judah','parent')],'1KI 16:28-31;1KI 22:51-53;2KI 3:1;2KI 8:16-29;2KI 11:1-3')

trails=[
dict(id='watchers',title='Before the waters rose',subtitle='Genesis, Enoch, and Jubilees in conversation',icon='star',steps=['enoch','watchers','forbidden-arts','judgment-watchers','noah-birth','flood','mastema']),
dict(id='presence',title='Where God dwells',subtitle='From the garden to the city in ashes',icon='temple',steps=['eden','jacob-bethel','tabernacle','ark-captured','ark-jerusalem','temple','jerusalem-falls']),
dict(id='family',title='An unlikely royal family',subtitle='Follow the people inside the promise',icon='branch',steps=['abraham-call','isaac','jacob','judah-tamar','ruth','david','covenant-david','jehoiachin-release']),
dict(id='kingdoms',title='Meanwhile, in the other kingdom',subtitle='The north and south keep crossing paths',icon='crown',steps=['kingdom-split','ahab','jehoshaphat','ramoth-battle','jehu-revolt','athaliah','fall-samaria']),
dict(id='women',title='Women who turn the story',subtitle='Courage, consequence, and voices worth hearing',icon='branch',steps=['hagar','judah-tamar','miriam','rahab','deborah','ruth','hannah','huldah']),
dict(id='exile',title='How a kingdom unravels',subtitle='Warnings, reform, and an unfinished ending',icon='city',steps=['amos','hosea','fall-samaria','assyrian-siege','lost-scroll','first-exile','jerusalem-falls','jehoiachin-release']),
]
prophet_windows=[
('samuel',1080,1010),('nathan',1000,960),('ahijah',940,900),('elijah',875,850),('micaiah',855,850),('elisha',855,795),('jonah',790,750),('amos',770,750),('hosea',755,715),('isaiah',740,685),('micah',740,700),('nahum',660,612),('zephaniah',640,609),('huldah',630,615),('jeremiah',627,580),('habakkuk',620,590),('ezekiel',593,570)]
extend(eras, entries, places, families, trails, refs)
data=dict(version=2,title='BibleBucket Interactive Bible Timeline',eras=eras,entries=entries,places=places,families=families,trails=trails,prophetWindows=[dict(id=i,start=s,end=e) for i,s,e in prophet_windows])
ids=[e['id'] for e in entries]
assert len(ids)==len(set(ids)), 'Duplicate entity ID'
for e in entries:
    assert set(e['related'])<=set(ids),(e['id'],'unknown related entry',set(e['related'])-set(ids))
    assert set(e['places'])<={p['id'] for p in places},(e['id'],'unknown place')
for f in families:
    assert {n['id'] for n in f['nodes']}<=set(ids),f['id']
for trail in trails:
    assert set(trail['steps'])<=set(ids),trail['id']
ROOT.mkdir(exist_ok=True)
(ROOT/'data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(f'{len(entries)} entries · {len(rulers)} rulers · {len(places)} places · {len(families)} family trees · {len(trails)} trails')
